// Hyniqe Growth website. Everything shown comes from the product itself:
// health-core.js and data.js are generated by scripts/build-site.ts, and
// DASHBOARD is a real week-1 run of both demo companies.
import { checkPage } from './health-core.js';
import { AGENTS, DASHBOARD, DEMO_SITES, RULES } from './data.js';

// Where the links point. They go to main, so they work once the growth branch is merged.
const REPO = 'https://github.com/HiteshChakravarti/Hyniqe';
const BRANCH = 'main';
const LINKS = {
  repo: `${REPO}/tree/${BRANCH}/growth`,
  samples: `${REPO}/blob/${BRANCH}/growth/samples/README.md`,
  hyniqe: REPO,
};
for (const [attr, href] of [['data-repo', LINKS.repo], ['data-samples', LINKS.samples], ['data-hyniqe', LINKS.hyniqe]]) {
  document.querySelectorAll(`[${attr}]`).forEach((a) => { a.href = href; a.rel = 'noopener'; });
}

const $ = (s, root = document) => root.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// Event lines from the product use **bold** markdown; escape first, then bold.
const md = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\*(.+?)\*/g, '<i>$1</i>');
const agentName = (id) => AGENTS.find((a) => a.id === id)?.name ?? id;
const STATUS = { published: 'Published', done: 'Done', pending_approval: 'Needs approval', changes_requested: 'Changes requested', rejected: 'Rejected', replied: 'Replied', new: 'New', qualified: 'Qualified', disqualified: 'Ignored' };
const tag = (s, label) => `<span class="tag s-${esc(s)}">${esc(label ?? STATUS[s] ?? s)}</span>`;
const waiting = (c) => c.tasks.filter((t) => t.status === 'pending_approval' || t.status === 'changes_requested');

// ---- team section ----
$('#agents').innerHTML = AGENTS.map((a) => `
  <div class="agent reveal${a.id === 'marketing-lead' ? ' lead' : ''}">
    <div class="top"><div class="av">${esc(a.name[0])}</div><div><div class="name">${esc(a.name)}</div><div class="role">${esc(a.title)}</div></div></div>
    <p>${esc(a.does)}</p>
    <div class="covers">Covers the job of: ${esc(a.replaces)}</div>
  </div>`).join('');

// ---- the dashboard preview ----
const VIEWS = [
  ['overview', 'Overview'],
  ['approvals', 'Approvals'],
  ['week', 'This week'],
  ['leads', 'Leads'],
  ['report', 'Friday report'],
  ['health', 'Health check'],
  ['team', 'Team'],
];
const state = { co: 0, view: 'overview', task: -1 };

function ring(score, verdict, track = 'rgba(159,227,242,.12)') {
  const color = verdict === 'Healthy' ? '#6fe0b3' : verdict === 'Needs work' ? '#f7c35f' : '#ff8fb5';
  const r = 40, c = 2 * Math.PI * r;
  return `<svg viewBox="0 0 96 96" role="img" aria-label="Score ${score} out of 100">
    <circle cx="48" cy="48" r="${r}" fill="none" stroke="${track}" stroke-width="8"/>
    <circle cx="48" cy="48" r="${r}" fill="none" stroke="${color}" stroke-width="8" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c * (1 - score / 100)}" transform="rotate(-90 48 48)"/>
    <text x="48" y="57" text-anchor="middle" fill="${color}" style="font:700 26px var(--sans);letter-spacing:-.04em">${score}</text></svg>`;
}

function kpis(c) {
  const m = c.report.metrics;
  const w = waiting(c).length;
  return `<div class="row r4">
    <div class="panel kpi good"><b>${m.Published}</b><span>published this week</span></div>
    <div class="panel kpi${w ? ' warn' : ''}"><b>${w}</b><span>waiting for a person</span></div>
    <div class="panel kpi"><b>${m['New leads']}</b><span>new leads</span></div>
    <div class="panel kpi good"><b>${m['A-grade leads']}</b><span>A-grade leads</span></div>
  </div>`;
}

function overview(c) {
  const todo = [
    ...waiting(c).map((t) => [`${t.title}`, `${t.agent} · waiting for ${t.approver}`, 'approvals']),
    ...c.leads.filter((l) => l.grade === 'A' && l.status !== 'replied').map((l) => [`Reply to ${l.name}`, 'A-grade lead', 'leads']),
  ];
  return `<h4>Week 1 overview</h4><p class="sub">Goal from Nova, Head of Marketing: ${esc(c.plan.goal)}</p>
    ${kpis(c)}
    <div class="row r2">
      <div class="panel"><h5>What to do next</h5><ul class="lines">${todo.length ? todo.map(([t, s]) => `<li><span class="sev warning"></span><div>${esc(t)}<div class="meta">${esc(s)}</div></div></li>`).join('') : '<li>All caught up.</li>'}</ul></div>
      <div class="panel"><h5>Website health</h5><div class="mini-ring">${ring(c.health.score, c.health.verdict)}<div><b>${esc(c.health.verdict)}</b><div class="meta dim" style="font-size:13px">${c.health.leaks.filter((l) => l.severity === 'critical').length} critical leaks, ${c.health.leaks.length} fixes assigned to agents</div></div></div></div>
    </div>
    <div class="panel"><h5>What the people did this week</h5><ul class="lines">${c.events.map((e) => `<li><div>${md(e)}</div></li>`).join('')}</ul></div>`;
}

function approvals(c) {
  const items = c.tasks.filter((t) => t.approver !== 'Auto' && t.status !== 'done');
  const open = items.filter((t) => t.status === 'pending_approval' || t.status === 'changes_requested');
  const decided = items.filter((t) => !open.includes(t));
  const card = (t) => `<div class="qitem${t.flagged ? ' flagged' : ''}">
      <div class="top"><div class="av">${esc(t.agent[0])}</div><b>${esc(t.title)}</b>${t.flagged ? tag('flag', 'Was flagged') : ''}${tag(t.status)}</div>
      <p class="gate">${esc(t.agent)}, ${esc(t.agentTitle)} · ${esc(t.channel)} · risk ${esc(t.risk)} · ${esc(t.gate)}</p>
      <div class="draft">${esc(t.excerpt)}</div>
      ${t.comments.map((x) => `<p class="note"><b>${esc(x.by)}:</b> “${esc(x.text)}”</p>`).join('')}
      ${open.includes(t)
        ? `<div class="acts"><span class="yes">Approve</span><span>Edit</span><span>Request changes</span><span>Reject</span><span>Reassign</span></div><p class="note">Waiting for <b>${esc(t.approver)}</b></p>`
        : `<p class="note">${esc(STATUS[t.status] ?? t.status)} by <b>${esc(t.decidedBy || t.approver)}</b></p>`}
    </div>`;
  return `<h4>Approvals</h4><p class="sub">${c.mode === 'Autopilot' ? `Only risky work comes here, to ${esc(c.owner)}. Everything else ran on its own.` : 'Each agent\'s work goes to the teammate who owns that area.'}</p>
    <div class="queue">${open.map(card).join('') || '<div class="panel">Nothing waiting.</div>'}</div>
    <div class="panel" style="margin-top:12px"><h5>Decided this week (${decided.length})</h5><ul class="lines">${decided.map((t) => `<li><div class="av">${esc(t.agent[0])}</div><div>${esc(t.title)}${t.comments.map((x) => `<div class="meta">${esc(x.by)}: “${esc(x.text)}”</div>`).join('')}<div class="meta">${esc(STATUS[t.status] ?? t.status)} by ${esc(t.decidedBy || t.approver)}${t.flagged ? ' · was flagged, fixed by the agent' : ''}</div></div>${tag(t.status)}</li>`).join('')}</ul></div>`;
}

function week(c) {
  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
  const t = c.tasks[state.task];
  return `<h4>This week</h4><p class="sub">Everything the agents produced, by day. Click an item to open the draft.</p>
    <div class="legend">${tag('published', 'Published or done')}${tag('pending_approval', 'Waiting')}${tag('rejected', 'Rejected')}</div>
    <div class="week">${days.map((d) => `<div><h6>${d}</h6>${c.tasks.map((x, i) => [x, i]).filter(([x]) => x.day === d).map(([x, i]) => `<button class="chipcard st-${x.status}" data-task="${i}" aria-pressed="${i === state.task}"><b>${esc(x.title)}</b><span>${esc(x.agent)} · ${esc(STATUS[x.status] ?? x.status)}</span></button>`).join('')}</div>`).join('')}</div>
    ${t ? `<div class="qitem" style="margin-top:4px"><div class="top"><div class="av">${esc(t.agent[0])}</div><b>${esc(t.title)}</b>${tag(t.status)}</div><p class="gate">${esc(t.agent)}, ${esc(t.agentTitle)} · ${esc(t.channel)} · ${esc(t.gate)}</p><div class="draft" style="max-height:none;-webkit-mask-image:none;mask-image:none">${esc(t.excerpt)}</div></div>` : ''}`;
}

function leads(c) {
  return `<h4>Leads</h4><p class="sub">Every lead is scored A, B or C with reasons, routed${c.mode === 'Copilot' ? ' to sales' : ''}, and gets a reply drafted at once.</p>
    <div class="panel" style="padding:6px 10px"><table class="t"><thead><tr><th></th><th>Lead</th><th class="hide-s">Why</th><th>Routed to</th><th>First reply</th></tr></thead><tbody>
    ${[...c.leads].sort((a, b) => b.score - a.score).map((l) => `<tr><td><div class="grade g-${l.grade}">${l.score === 0 ? '0' : l.grade}</div></td>
      <td><b>${esc(l.name)}</b>${l.company ? `, ${esc(l.company)}` : ''}<span class="why msg">“${esc(l.message)}”</span></td>
      <td class="hide-s"><span class="why">${esc(l.reasons.join(' · '))}</span></td>
      <td>${esc(l.routeTo)}</td><td>${esc(l.reply)}</td></tr>`).join('')}
    </tbody></table></div>
    ${c.leads.filter((l) => l.grade === 'A').slice(0, 1).map((l) => `<div class="qitem" style="margin-top:12px"><div class="top"><div class="grade g-A">A</div><b>Reply drafted for ${esc(l.name)}</b></div><div class="draft">${esc(l.replyDraft)}</div></div>`).join('')}`;
}

function report(c) {
  const m = c.report.metrics;
  const show = ['Published', 'Website visits', 'New leads', 'Conversion rate %', 'Replied within 5 min', 'Ad spend', 'Cost per lead', 'Flagged by content guard'].filter((k) => k in m);
  return `<h4>Friday report, week 1</h4><p class="sub">Written by Quinn, ${esc(AGENTS.find((a) => a.name === 'Quinn')?.title ?? 'Marketing Analyst')}. Its lessons go straight into next Monday's plan.</p>
    <div class="row r4">${show.map((k) => `<div class="panel kpi"><b>${m[k]}${k.includes('%') ? '%' : ''}</b><span>${esc(k.replace(' %', ''))}</span></div>`).join('')}</div>
    <div class="row r2">
      <div class="panel"><h5>What went well</h5><ul class="bullets">${c.report.wins.map((w) => `<li>${esc(w)}</li>`).join('')}</ul></div>
      <div class="panel"><h5>What got in the way</h5><ul class="bullets">${c.report.problems.map((w) => `<li>${esc(w)}</li>`).join('') || '<li>Nothing.</li>'}</ul></div>
    </div>
    <div class="panel"><h5>Next week</h5><ul class="bullets">${c.report.nextWeek.map((w) => `<li>${esc(w)}</li>`).join('')}</ul></div>`;
}

function health(c) {
  const h = c.health;
  return `<h4>Marketing health check</h4><p class="sub">${esc(c.website)} · ${h.passed} of 19 checks passed</p>
    <div class="panel" style="margin-bottom:12px"><div class="mini-ring">${ring(h.score, h.verdict)}<div><b style="font-size:20px">${esc(h.verdict)}</b><p class="dim" style="font-size:13px">${esc(h.summary)}</p></div></div></div>
    <div class="panel"><h5>Leaks, each assigned to an agent</h5><ul class="lines">${h.leaks.slice(0, 8).map((f) => `<li><span class="sev ${f.severity}"></span><div>${esc(f.title)}<div class="meta">${esc(f.fix)}</div></div><span class="tag">${esc(f.agent)}</span></li>`).join('')}</ul>${h.leaks.length > 8 ? `<p class="meta dim" style="margin-top:8px;font-size:12px">and ${h.leaks.length - 8} more</p>` : ''}</div>`;
}

function team(c) {
  if (c.mode === 'Autopilot') return `<h4>Team</h4><p class="sub">No marketing team needed in Autopilot.</p>
    <div class="panel"><p>The agents do the work; <b>${esc(c.owner)}</b> approves only what is risky. Trust level: <b>${esc(c.trust)}</b>.</p><p class="dim" style="margin-top:8px">If you have marketing people, switch to Copilot: every agent's work then goes to the person who owns that area. See Ledgerly above.</p></div>`;
  return `<h4>Team</h4><p class="sub">Who reviews which agent's work. Leads go to sales.</p>
    <div class="row r2" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr))">${c.team.map((m) => `<div class="panel"><div style="display:flex;gap:10px;align-items:center;margin-bottom:10px"><div class="av" style="background:var(--accent-2)">${esc(m.name[0])}</div><div><b>${esc(m.name)}</b><div class="meta dim" style="font-size:12px">${esc(m.role)}</div></div></div><div style="display:flex;flex-wrap:wrap;gap:6px">${m.reviews.map((a) => `<span class="tag">${esc(a)}</span>`).join('')}</div><p class="meta dim" style="font-size:12px;margin-top:12px">${waiting(c).filter((t) => t.approver === m.name).length} waiting · ${c.tasks.filter((t) => t.decidedBy === m.name).length} decided this week${c.leads.some((l) => l.routeTo === m.name) ? ` · ${c.leads.filter((l) => l.routeTo === m.name).length} leads` : ''}</p></div>`).join('')}</div>
    <div class="panel" style="margin-top:12px"><h5>How work is routed</h5><p class="dim" style="font-size:13px">Every draft goes to the person who owns that agent. They can approve, edit, request changes, comment or reassign. The owner sees every queue.</p></div>`;
}

const RENDER = { overview, approvals, week, leads, report, health, team };

function frame(c, view, interactive) {
  return `<div class="app-bar"><div class="dots"><i></i><i></i><i></i></div><div class="addr">127.0.0.1:4400 · ${esc(c.name)}</div><div class="who">${esc(c.mode)}${c.trust ? ` · ${esc(c.trust)}` : ''}</div></div>
    <div class="app-body">
      <div class="app-side" role="tablist" aria-label="Dashboard screens">
        <div class="co"><b>${esc(c.name)}</b><span>${esc(c.mode)} · week 1</span></div>
        ${VIEWS.map(([id, label]) => `<button role="tab" ${interactive ? `data-view="${id}"` : 'tabindex="-1"'} aria-selected="${id === view}">${label}${id === 'approvals' && waiting(c).length ? `<span class="n">${waiting(c).length}</span>` : ''}</button>`).join('')}
      </div>
      <div class="app-main">${RENDER[view](c)}</div>
    </div>`;
}

function drawDash() {
  const c = DASHBOARD[state.co];
  $('#dash').innerHTML = frame(c, state.view, true);
  $('#co-mode').textContent = c.mode === 'Autopilot' ? `${c.name}: no marketing team. ${c.owner} only approves what is risky.` : `${c.name}: a ${c.team.length}-person team. Each agent's work goes to its owner.`;
  $('#co-switch').querySelectorAll('button').forEach((b, i) => b.setAttribute('aria-selected', String(i === state.co)));
}

$('#co-switch').innerHTML = DASHBOARD.map((c, i) => `<button role="tab" data-co="${i}">${esc(c.name)}<small>${esc(c.mode)}</small></button>`).join('');
$('#co-switch').addEventListener('click', (e) => {
  const b = e.target.closest('[data-co]');
  if (!b) return;
  state.co = Number(b.dataset.co);
  state.task = -1;
  drawDash();
});
$('#dash').addEventListener('click', (e) => {
  const v = e.target.closest('[data-view]');
  const t = e.target.closest('[data-task]');
  if (v) { state.view = v.dataset.view; state.task = -1; drawDash(); }
  if (t) { const i = Number(t.dataset.task); state.task = state.task === i ? -1 : i; drawDash(); }
});
drawDash();
$('#hero-app').innerHTML = frame(DASHBOARD[0], 'overview', false);

// ---- health check ----
const ORDER = { critical: 0, warning: 1, info: 2 };
const COLOR = { 'Leaking leads': '#b0104a', 'Needs work': '#8a5200', Healthy: '#0b7f5c' };

function show(h) {
  const color = COLOR[h.verdict];
  const failed = h.findings.filter((f) => !f.passed).sort((a, b) => ORDER[a.severity] - ORDER[b.severity]);
  const passed = h.findings.filter((f) => f.passed);
  const el = $('#result');
  el.className = 'card result';
  el.innerHTML = `
    <div class="verdict-row"><div class="ring">${ring(h.score, h.verdict, '#dfeef2').replace(/#6fe0b3|#f7c35f|#ff8fb5/g, color)}</div><div><h3 style="color:${color}">${esc(h.verdict)}</h3><p>${esc(h.summary)}</p></div></div>
    <ul class="findings">
      ${failed.map((f) => `<li><span class="dot ${f.severity}"></span><div><b>${esc(f.title)}</b><div class="ev">${esc(f.evidence)}</div><div class="fix">${esc(f.fix)}</div></div><span class="who">${esc(agentName(f.agent))} fixes</span></li>`).join('')}
    </ul>
    <details class="passed"><summary>${passed.length} checks passed</summary><ul class="findings">${passed.map((f) => `<li><span class="dot pass"></span><div><b>${esc(f.title)}</b><div class="ev">${esc(f.evidence)}</div></div><span></span></li>`).join('')}</ul></details>`;
}

function run(url, html) {
  $('#err').textContent = '';
  if (!html.trim()) {
    $('#err').textContent = 'Paste your page\'s HTML first, or try one of the sample sites.';
    $('#html').focus();
    return;
  }
  if (!/<[a-z!]/i.test(html)) {
    $('#err').textContent = 'That doesn\'t look like HTML. Open your site, press Ctrl+U, and copy the whole page source.';
    return;
  }
  const found = html.match(/<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']+)/i)?.[1] || html.match(/<meta[^>]+property=["']og:url["'][^>]*content=["']([^"']+)/i)?.[1];
  show(checkPage(RULES, { url: url || found || 'pasted-html', html }));
}

$('#html').addEventListener('input', () => { $('#err').textContent = ''; });
$('#run').addEventListener('click', () => run('', $('#html').value));
document.querySelectorAll('[data-demo]').forEach((b) => b.addEventListener('click', () => {
  const d = DEMO_SITES[b.dataset.demo];
  $('#html').value = d.html;
  run(d.url, d.html);
}));

// ---- small touches ----
const links = [...document.querySelectorAll('.tabs a')];
const io = new IntersectionObserver((es) => es.forEach((e) => {
  if (e.isIntersecting) links.forEach((a) => a.classList.toggle('on', a.getAttribute('href') === `#${e.target.id}`));
}), { rootMargin: '-45% 0px -50% 0px' });
links.forEach((a) => { const s = document.querySelector(a.getAttribute('href')); if (s) io.observe(s); });
const rv = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('in'); rv.unobserve(e.target); } }), { threshold: 0.12 });
document.querySelectorAll('.reveal').forEach((el) => rv.observe(el));
